//! Builds the four generated files as strings.
//!
//! - `runtime/src/generated.rs`: import table and error codes (host side)
//! - `bindings/rust/src/generated.rs`: extern declarations and enums (guest side)
//! - `bindings/assemblyscript/assembly/generated.ts`: extern declarations and enums (guest side)
//! - `bindings/c/generated.h`: extern declarations and enums (guest side)

use std::fmt::Write as _;

use crate::model::{EnumDef, FlagsDef, Hal, Iface, Import, Ret};

/// Banner at the top of every generated file.
fn banner(hal: &Hal, comment: &str) -> String {
    match &hal.device_package {
        None => format!(
            "{c} @generated by `cargo run -p wasmicon-gen` from `wit/` ({pkg}). DO NOT EDIT.\n\
             {c} Lowering rules: docs/abi-spec.md.\n",
            c = comment,
            pkg = hal.package
        ),
        Some(dev) => format!(
            "{c} @generated by `cargo run -p wasmicon-gen` from `wit/` ({pkg}) and\n\
             {c} `wit-device/` ({dev}). DO NOT EDIT.\n\
             {c} Lowering rules: docs/abi-spec.md.\n",
            c = comment,
            pkg = hal.package
        ),
    }
}

fn rust_doc(out: &mut String, indent: &str, docs: &[String]) {
    for line in docs {
        if line.is_empty() {
            let _ = writeln!(out, "{indent}///");
        } else {
            let _ = writeln!(out, "{indent}/// {line}");
        }
    }
}

/// Keeps a `*/` inside a WIT doc comment from closing the JSDoc block early.
/// Nothing in this workspace compiles the generated `.ts`, so without this a
/// broken file would be committed unnoticed.
fn ts_escape(line: &str) -> String {
    line.replace("*/", "*\\/")
}

fn ts_doc(out: &mut String, indent: &str, docs: &[String]) {
    if docs.is_empty() {
        return;
    }
    let _ = writeln!(out, "{indent}/**");
    for line in docs {
        let _ = writeln!(out, "{indent} * {}", ts_escape(line));
    }
    let _ = writeln!(out, "{indent} */");
}

/// Avoids Rust keywords: `self` becomes `this` (docs/abi-spec.md Appendix A).
fn rust_param_name(name: &str) -> String {
    match name {
        "self" => "this".to_string(),
        other => crate::lower::snake(other),
    }
}

/// AssemblyScript parameter names are lowerCamelCase (docs/abi-spec.md Appendix B).
fn ts_param_name(name: &str) -> String {
    let mut parts = name.split(['-', '.']).filter(|p| !p.is_empty());
    let mut s = parts.next().unwrap_or_default().to_string();
    for p in parts {
        s.push_str(&crate::lower::pascal(p));
    }
    s
}

/// Emits a Rust enum. `extra` holds additional `impl` items.
fn rust_enum(out: &mut String, indent: &str, e: &EnumDef, extra: &str) {
    rust_doc(out, indent, &e.docs);
    let _ = writeln!(out, "{indent}#[derive(Clone, Copy, PartialEq, Eq)]");
    let _ = writeln!(out, "{indent}#[repr(u32)]");
    let _ = writeln!(out, "{indent}pub enum {} {{", e.rust_name);
    for (i, c) in e.cases.iter().enumerate() {
        rust_doc(out, &format!("{indent}    "), &c.docs);
        let _ = writeln!(out, "{indent}    {} = {i},", c.ident);
    }
    let _ = writeln!(out, "{indent}}}");
    let _ = writeln!(out);
    let _ = writeln!(out, "{indent}impl {} {{", e.rust_name);
    let _ = writeln!(out, "{indent}    /// Number of cases.");
    let _ = writeln!(out, "{indent}    pub const COUNT: u32 = {};", e.cases.len());
    let _ = writeln!(out);
    let _ = writeln!(
        out,
        "{indent}    /// Converts from a discriminant. Out of range gives `None` (docs/abi-spec.md §4.1)."
    );
    let _ = writeln!(out, "{indent}    #[must_use]");
    let _ = writeln!(
        out,
        "{indent}    pub const fn from_u32(v: u32) -> Option<Self> {{"
    );
    let _ = writeln!(out, "{indent}        match v {{");
    for (i, c) in e.cases.iter().enumerate() {
        let _ = writeln!(out, "{indent}            {i} => Some(Self::{}),", c.ident);
    }
    let _ = writeln!(out, "{indent}            _ => None,");
    let _ = writeln!(out, "{indent}        }}");
    let _ = writeln!(out, "{indent}    }}");
    out.push_str(extra);
    let _ = writeln!(out, "{indent}}}");
}

/// Emits flags as a set of constants (docs/abi-spec.md §4.1).
fn rust_flags(out: &mut String, indent: &str, f: &FlagsDef) {
    rust_doc(out, indent, &f.docs);
    let _ = writeln!(out, "{indent}pub struct {};", f.rust_name);
    let _ = writeln!(out);
    let _ = writeln!(out, "{indent}impl {} {{", f.rust_name);
    for (i, b) in f.bits.iter().enumerate() {
        rust_doc(out, &format!("{indent}    "), &b.docs);
        let _ = writeln!(out, "{indent}    pub const {}: u32 = 1 << {i};", b.ident);
    }
    let _ = writeln!(out);
    let _ = writeln!(
        out,
        "{indent}    /// Mask of the defined bits. Any other bit set means `invalid-argument`."
    );
    let _ = writeln!(
        out,
        "{indent}    pub const ALL: u32 = {:#x};",
        flags_mask(f)
    );
    let _ = writeln!(out, "{indent}}}");
}

fn flags_mask(f: &FlagsDef) -> u32 {
    if f.bits.len() >= 32 {
        u32::MAX
    } else {
        (1u32 << f.bits.len()) - 1
    }
}

fn error_code_extra(indent: &str) -> String {
    let mut s = String::new();
    let _ = writeln!(s);
    let _ = writeln!(
        s,
        "{indent}    /// Status value the host returns: discriminant + 1 (docs/abi-spec.md §4.4)."
    );
    let _ = writeln!(s, "{indent}    #[must_use]");
    let _ = writeln!(s, "{indent}    pub const fn status(self) -> u32 {{");
    let _ = writeln!(s, "{indent}        self as u32 + 1");
    let _ = writeln!(s, "{indent}    }}");
    let _ = writeln!(s);
    let _ = writeln!(
        s,
        "{indent}    /// Recovers the error code from a status value. 0 (success) and out of range give `None`."
    );
    let _ = writeln!(s, "{indent}    #[must_use]");
    let _ = writeln!(
        s,
        "{indent}    pub const fn from_status(status: u32) -> Option<Self> {{"
    );
    let _ = writeln!(s, "{indent}        if status == 0 {{");
    let _ = writeln!(s, "{indent}            return None;");
    let _ = writeln!(s, "{indent}        }}");
    let _ = writeln!(s, "{indent}        Self::from_u32(status - 1)");
    let _ = writeln!(s, "{indent}    }}");
    s
}

fn is_error_code(e: &EnumDef) -> bool {
    e.wit_name == "error-code"
}

// ---------------------------------------------------------------- runtime

/// Builds `runtime/src/generated.rs`.
pub fn runtime_rs(hal: &Hal) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "//! Import table and error codes of the Wasmicon HAL (host side)."
    );
    let _ = writeln!(out, "//!");
    for line in banner(hal, "//!").lines() {
        let _ = writeln!(out, "{line}");
    }
    let _ = writeln!(out);

    let _ = writeln!(
        out,
        "/// Package name and version of the HAL (the ABI version). The firmware announces it at boot."
    );
    let _ = writeln!(out, "pub const PACKAGE: &str = \"{}\";", hal.package);
    let _ = writeln!(out);
    if let Some(dev) = &hal.device_package {
        let _ = writeln!(
            out,
            "/// Package name and version of the device layer. It moves independently of `PACKAGE`."
        );
        let _ = writeln!(out, "pub const DEVICE_PACKAGE: &str = \"{dev}\";");
        let _ = writeln!(out);
    }

    let _ = writeln!(out, "/// Descriptor of one HAL import.");
    let _ = writeln!(out, "pub struct ImportDesc {{");
    let _ = writeln!(out, "    /// Import module name (docs/abi-spec.md §3.1).");
    let _ = writeln!(out, "    pub module: &'static str,");
    let _ = writeln!(out, "    /// Import field name (docs/abi-spec.md §3.2).");
    let _ = writeln!(out, "    pub name: &'static str,");
    let _ = writeln!(
        out,
        "    /// Signature as `params:results`: `i` = i32, `I` = i64, `f` = f32, `F` = f64."
    );
    let _ = writeln!(out, "    pub sig: &'static str,");
    let _ = writeln!(out, "    /// Slot the port layer dispatches on.");
    let _ = writeln!(out, "    pub host_fn: HostFn,");
    let _ = writeln!(out, "}}");
    let _ = writeln!(out);

    let _ = writeln!(
        out,
        "/// Host function slots, one per element of `IMPORTS`."
    );
    let _ = writeln!(out, "#[derive(Clone, Copy, PartialEq, Eq)]");
    let _ = writeln!(out, "#[repr(u16)]");
    let _ = writeln!(out, "pub enum HostFn {{");
    for (iface, f) in hal.imports() {
        let _ = writeln!(out, "    /// `{}` in `{}`", f.name, iface.module);
        let _ = writeln!(out, "    {},", f.slot);
    }
    let _ = writeln!(out, "}}");
    let _ = writeln!(out);

    let n = hal.imports().count();
    let _ = writeln!(out, "impl HostFn {{");
    let _ = writeln!(out, "    /// Index into `IMPORTS`.");
    let _ = writeln!(out, "    #[must_use]");
    let _ = writeln!(out, "    pub const fn index(self) -> u16 {{");
    let _ = writeln!(out, "        self as u16");
    let _ = writeln!(out, "    }}");
    let _ = writeln!(out);
    let _ = writeln!(out, "    /// Converts from an index.");
    let _ = writeln!(out, "    #[must_use]");
    let _ = writeln!(
        out,
        "    pub const fn from_index(i: u16) -> Option<Self> {{"
    );
    let _ = writeln!(out, "        match i {{");
    for (i, (_, f)) in hal.imports().enumerate() {
        let _ = writeln!(out, "            {i} => Some(Self::{}),", f.slot);
    }
    let _ = writeln!(out, "            _ => None,");
    let _ = writeln!(out, "        }}");
    let _ = writeln!(out, "    }}");
    let _ = writeln!(out, "}}");
    let _ = writeln!(out);
    let _ = writeln!(
        out,
        "/// All imports of the HAL and the device layer (docs/abi-spec.md §7)."
    );
    let _ = writeln!(out, "pub static IMPORTS: [ImportDesc; {n}] = [");
    for (iface, f) in hal.imports() {
        let _ = writeln!(out, "    ImportDesc {{");
        let _ = writeln!(out, "        module: \"{}\",", iface.module);
        let _ = writeln!(out, "        name: \"{}\",", f.name);
        let _ = writeln!(out, "        sig: \"{}\",", f.sig());
        let _ = writeln!(out, "        host_fn: HostFn::{},", f.slot);
        let _ = writeln!(out, "    }},");
    }
    let _ = writeln!(out, "];");
    let _ = writeln!(out);

    let _ = writeln!(
        out,
        "/// Looks up an import by module and field name. The caller checks `sig`."
    );
    let _ = writeln!(out, "#[must_use]");
    let _ = writeln!(
        out,
        "pub fn resolve(module: &str, name: &str) -> Option<&'static ImportDesc> {{"
    );
    let _ = writeln!(
        out,
        "    IMPORTS.iter().find(|d| d.module == module && d.name == name)"
    );
    let _ = writeln!(out, "}}");

    for iface in &hal.interfaces {
        if iface.enums.is_empty() && iface.flags.is_empty() {
            continue;
        }
        let _ = writeln!(out);
        rust_doc(&mut out, "", &iface.docs);
        let _ = writeln!(out, "pub mod {} {{", crate::lower::snake(&iface.name));
        for (i, e) in iface.enums.iter().enumerate() {
            if i > 0 {
                let _ = writeln!(out);
            }
            let extra = if is_error_code(e) {
                error_code_extra("    ")
            } else {
                String::new()
            };
            rust_enum(&mut out, "    ", e, &extra);
        }
        for (i, f) in iface.flags.iter().enumerate() {
            if i > 0 || !iface.enums.is_empty() {
                let _ = writeln!(out);
            }
            rust_flags(&mut out, "    ", f);
        }
        let _ = writeln!(out, "}}");
    }

    if let Some(iface) = hal.interfaces.iter().find(|i| i.name == "types")
        && iface.enums.iter().any(is_error_code)
    {
        let _ = writeln!(out);
        let _ = writeln!(out, "pub use self::types::ErrorCode;");
    }

    out
}

// ---------------------------------------------------------------- bindings/rust

/// Builds `bindings/rust/src/generated.rs`.
pub fn bindings_rs(hal: &Hal) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "//! Guest-side extern declarations and enums of the Wasmicon HAL."
    );
    let _ = writeln!(out, "//!");
    for line in banner(hal, "//!").lines() {
        let _ = writeln!(out, "{line}");
    }

    for iface in &hal.interfaces {
        let _ = writeln!(out);
        rust_doc(&mut out, "", &iface.docs);
        let _ = writeln!(out, "pub mod {} {{", crate::lower::snake(&iface.name));

        if !iface.imports.is_empty() {
            let _ = writeln!(
                out,
                "    #[link(wasm_import_module = \"{}\")]",
                iface.module
            );
            let _ = writeln!(out, "    unsafe extern \"C\" {{");
            for (i, f) in iface.imports.iter().enumerate() {
                if i > 0 {
                    let _ = writeln!(out);
                }
                rust_doc(&mut out, "        ", &f.docs);
                let _ = writeln!(out, "        #[link_name = \"{}\"]", f.name);
                let args = f
                    .params
                    .iter()
                    .map(|p| format!("{}: {}", rust_param_name(&p.name), p.rust()))
                    .collect::<Vec<_>>()
                    .join(", ");
                let ret = f.ret.rust().map(|r| format!(" -> {r}")).unwrap_or_default();
                let _ = writeln!(out, "        pub fn {}({args}){ret};", f.rust_name);
            }
            let _ = writeln!(out, "    }}");
        }

        for (i, e) in iface.enums.iter().enumerate() {
            if !iface.imports.is_empty() || i > 0 {
                let _ = writeln!(out);
            }
            let extra = if is_error_code(e) {
                error_code_extra("    ")
            } else {
                String::new()
            };
            rust_enum(&mut out, "    ", e, &extra);
        }
        for f in &iface.flags {
            if !iface.imports.is_empty() || !iface.enums.is_empty() {
                let _ = writeln!(out);
            }
            rust_flags(&mut out, "    ", f);
        }
        let _ = writeln!(out, "}}");
    }

    out
}

// ---------------------------------------------------------------- bindings/assemblyscript

/// Builds `bindings/assemblyscript/assembly/generated.ts`.
pub fn bindings_ts(hal: &Hal) -> String {
    let mut out = String::new();
    out.push_str(&banner(hal, "//"));

    for iface in &hal.interfaces {
        let _ = writeln!(out);
        let _ = writeln!(out, "// ---- {} ----", iface.module);
        if !iface.docs.is_empty() {
            let _ = writeln!(out);
            ts_doc(&mut out, "", &iface.docs);
        }

        for e in &iface.enums {
            let _ = writeln!(out);
            ts_doc(&mut out, "", &e.docs);
            let _ = writeln!(out, "export enum {} {{", e.as_name);
            for (i, c) in e.cases.iter().enumerate() {
                ts_doc(&mut out, "  ", &c.docs);
                let _ = writeln!(out, "  {} = {i},", c.ident);
            }
            let _ = writeln!(out, "}}");
        }

        for fl in &iface.flags {
            let _ = writeln!(out);
            ts_doc(&mut out, "", &fl.docs);
            let _ = writeln!(
                out,
                "// docs/abi-spec.md §4.1: bits are assigned from bit 0 in declaration order."
            );
            for (i, b) in fl.bits.iter().enumerate() {
                ts_doc(&mut out, "", &b.docs);
                let _ = writeln!(
                    out,
                    "export const {}{}: u32 = {:#x};",
                    fl.as_name,
                    b.ident,
                    1u32 << i
                );
            }
            let _ = writeln!(
                out,
                "/** Mask of the defined bits. Any other bit set means `invalid-argument`. */"
            );
            let _ = writeln!(
                out,
                "export const {}All: u32 = {:#x};",
                fl.as_name,
                flags_mask(fl)
            );
        }

        for f in &iface.imports {
            let _ = writeln!(out);
            ts_doc(&mut out, "", &f.docs);
            let _ = writeln!(out, "@external(\"{}\", \"{}\")", iface.module, f.name);
            let args = f
                .params
                .iter()
                .map(|p| format!("{}: {}", ts_param_name(&p.name), p.assemblyscript()))
                .collect::<Vec<_>>()
                .join(", ");
            let ret = ts_ret(f);
            let _ = writeln!(out, "export declare function {}({args}): {ret};", f.as_name);
        }
    }

    out
}

fn ts_ret(f: &Import) -> String {
    match &f.ret {
        Ret::None => "void".to_string(),
        Ret::Status => "u32".to_string(),
        Ret::Scalar(s) => s.assemblyscript().to_string(),
    }
}

// ---------------------------------------------------------------- bindings/c

/// Emits a C doc comment. A `*/` would close the block early, as in TS.
/// Blank lines carry no trailing space, which editors and diffs would show.
fn c_doc(out: &mut String, indent: &str, docs: &[String]) {
    if docs.is_empty() {
        return;
    }
    let _ = writeln!(out, "{indent}/**");
    for line in docs {
        if line.is_empty() {
            let _ = writeln!(out, "{indent} *");
        } else {
            let _ = writeln!(out, "{indent} * {}", ts_escape(line));
        }
    }
    let _ = writeln!(out, "{indent} */");
}

/// Prefixes a type name with `wasmicon_` and the interface name, because C has one flat
/// namespace. Only `types`, which holds the shared types, omits the interface name (the
/// same rule as AS).
fn c_type_prefix(iface: &Iface, wit_name: &str) -> String {
    let ty = crate::lower::snake(wit_name);
    if iface.name == "types" {
        format!("wasmicon_{ty}")
    } else {
        format!("wasmicon_{}_{ty}", crate::lower::snake(&iface.name))
    }
}

fn c_const(prefix: &str, wit_name: &str) -> String {
    format!("{prefix}_{}", crate::lower::snake(wit_name)).to_uppercase()
}

/// Builds `bindings/c/generated.h`.
pub fn bindings_c(hal: &Hal) -> String {
    let mut out = String::new();
    out.push_str(&banner(hal, "//"));
    let _ = writeln!(out);
    let _ = writeln!(out, "#ifndef WASMICON_HAL_GENERATED_H");
    let _ = writeln!(out, "#define WASMICON_HAL_GENERATED_H");
    let _ = writeln!(out);
    let _ = writeln!(out, "#include <stdint.h>");
    let _ = writeln!(out);
    let _ = writeln!(out, "#ifdef __cplusplus");
    let _ = writeln!(out, "extern \"C\" {{");
    let _ = writeln!(out, "#endif");
    let _ = writeln!(out);
    let _ = writeln!(
        out,
        "/** Package name and version of the HAL (the ABI version). */"
    );
    let _ = writeln!(out, "#define WASMICON_HAL_PACKAGE \"{}\"", hal.package);
    let _ = writeln!(out);
    if let Some(dev) = &hal.device_package {
        let _ = writeln!(
            out,
            "/** Package name and version of the device layer. It moves independently. */"
        );
        let _ = writeln!(out, "#define WASMICON_DEVICE_PACKAGE \"{dev}\"");
        let _ = writeln!(out);
    }
    let _ = writeln!(
        out,
        "/** Attribute for a HAL import declaration (docs/abi-spec.md §3). */"
    );
    let _ = writeln!(out, "#define WASMICON_IMPORT(module, name) \\");
    let _ = writeln!(
        out,
        "    __attribute__((import_module(module), import_name(name)))"
    );

    for iface in &hal.interfaces {
        let _ = writeln!(out);
        let _ = writeln!(out, "// ---- {} ----", iface.module);
        if !iface.docs.is_empty() {
            let _ = writeln!(out);
            c_doc(&mut out, "", &iface.docs);
        }

        for e in &iface.enums {
            let prefix = c_type_prefix(iface, &e.wit_name);
            let _ = writeln!(out);
            c_doc(&mut out, "", &e.docs);
            let _ = writeln!(out, "typedef enum {prefix} {{");
            for (i, c) in e.cases.iter().enumerate() {
                c_doc(&mut out, "    ", &c.docs);
                let _ = writeln!(out, "    {} = {i},", c_const(&prefix, &c.wit_name));
            }
            let _ = writeln!(out, "}} {prefix}_t;");
            let _ = writeln!(out);
            let _ = writeln!(
                out,
                "/** Number of cases. Any other value is invalid (docs/abi-spec.md §4.1). */"
            );
            let _ = writeln!(
                out,
                "#define {} {}u",
                c_const(&prefix, "count"),
                e.cases.len()
            );
            if is_error_code(e) {
                let _ = writeln!(out);
                let _ = writeln!(out, "/** Status value that means success. */");
                let _ = writeln!(out, "#define WASMICON_OK 0u");
                let _ = writeln!(out);
                let _ = writeln!(
                    out,
                    "/** Status value the host returns: discriminant + 1 (docs/abi-spec.md §4.4). */"
                );
                let _ = writeln!(
                    out,
                    "static inline uint32_t {prefix}_status({prefix}_t code) {{"
                );
                let _ = writeln!(out, "    return (uint32_t)code + 1u;");
                let _ = writeln!(out, "}}");
                let _ = writeln!(out);
                let _ = writeln!(
                    out,
                    "/** Recovers the error code from a status value. Returns 0 and leaves `*out` untouched for 0 (success) and out of range. */"
                );
                let _ = writeln!(
                    out,
                    "static inline int {prefix}_from_status(uint32_t status, {prefix}_t *out) {{"
                );
                let _ = writeln!(
                    out,
                    "    if (status == 0u || status > {}) {{",
                    c_const(&prefix, "count")
                );
                let _ = writeln!(out, "        return 0;");
                let _ = writeln!(out, "    }}");
                let _ = writeln!(out, "    *out = ({prefix}_t)(status - 1u);");
                let _ = writeln!(out, "    return 1;");
                let _ = writeln!(out, "}}");
            }
        }

        for fl in &iface.flags {
            let prefix = c_type_prefix(iface, &fl.wit_name);
            let _ = writeln!(out);
            c_doc(&mut out, "", &fl.docs);
            let _ = writeln!(
                out,
                "// docs/abi-spec.md §4.1: bits are assigned from bit 0 in declaration order."
            );
            for (i, b) in fl.bits.iter().enumerate() {
                c_doc(&mut out, "", &b.docs);
                let _ = writeln!(out, "#define {} (1u << {i})", c_const(&prefix, &b.wit_name));
            }
            let _ = writeln!(
                out,
                "/** Mask of the defined bits. Any other bit set means `invalid-argument`. */"
            );
            let _ = writeln!(
                out,
                "#define {} {:#x}u",
                c_const(&prefix, "all"),
                flags_mask(fl)
            );
        }

        for f in &iface.imports {
            let _ = writeln!(out);
            c_doc(&mut out, "", &f.docs);
            let _ = writeln!(out, "WASMICON_IMPORT(\"{}\", \"{}\")", iface.module, f.name);
            let args = if f.params.is_empty() {
                "void".to_string()
            } else {
                f.params
                    .iter()
                    .map(|p| {
                        let ty = p.c();
                        let sep = if ty.ends_with('*') { "" } else { " " };
                        format!("{ty}{sep}{}", crate::lower::snake(&p.name))
                    })
                    .collect::<Vec<_>>()
                    .join(", ")
            };
            let _ = writeln!(out, "{} wasmicon_{}({args});", f.ret.c(), f.as_name);
        }
    }

    let _ = writeln!(out);
    let _ = writeln!(out, "#ifdef __cplusplus");
    let _ = writeln!(out, "}}");
    let _ = writeln!(out, "#endif");
    let _ = writeln!(out);
    let _ = writeln!(out, "#endif // WASMICON_HAL_GENERATED_H");
    out
}

#[cfg(test)]
mod tests {
    use super::ts_escape;

    #[test]
    fn ts_escape_does_not_close_the_jsdoc_block() {
        let escaped = ts_escape("text with */ inside");
        assert!(
            !escaped.contains("*/"),
            "JSDoc block closes early: {escaped}"
        );
        assert_eq!(escaped, "text with *\\/ inside");
    }

    #[test]
    fn ts_escape_leaves_ordinary_text_alone() {
        assert_eq!(ts_escape("an ordinary comment"), "an ordinary comment");
    }
}
